//! `hick equiv`: weave two documents and prove no generated byte moved.
//!
//! Its own file because the argument struct, the comparison and the one
//! subtlety worth explaining — a document weaves a `.md` of its own name, so
//! two documents at different paths differ on that file before anything they
//! generate is looked at — belong together, and `main.rs` is at its length
//! baseline.

use std::path::PathBuf;
use std::process::ExitCode;

use anyhow::{Context, Result};
use hickory_cli::ExecutorChoice;

#[derive(clap::Args)]
pub struct EquivArgs {
    /// The document as it stands (the baseline).
    pub first: PathBuf,
    /// The restructured document to compare against it.
    pub second: PathBuf,
    /// Compare every output EXCEPT each document's own markdown weave.
    ///
    /// Two documents with different basenames are never equivalent without
    /// this: every document weaves a `.md` of its own name, so `a.hick` and
    /// `b.hick` differ on `a.md` and `b.md` before anything they generate is
    /// looked at. Use it when the two live at different paths — a document
    /// and the one that is meant to replace it — and what you are proving is
    /// that the generated files did not move.
    #[arg(long = "ignore-weave")]
    pub ignore_weave: bool,
}

pub async fn cmd_equiv(args: EquivArgs) -> Result<ExitCode> {
    use hickory_cli::{RunMode, run_doc};
    let first = run_doc(&args.first, &[], RunMode::Weave, ExecutorChoice::Local)
        .await
        .with_context(|| format!("weaving {}", args.first.display()))?;
    let second = run_doc(&args.second, &[], RunMode::Weave, ExecutorChoice::Local)
        .await
        .with_context(|| format!("weaving {}", args.second.display()))?;
    let (first_files, second_files) = match args.ignore_weave {
        false => (first.result.files.clone(), second.result.files.clone()),
        true => (
            without_own_weave(&first.result.files, &first.doc),
            without_own_weave(&second.result.files, &second.doc),
        ),
    };
    let diffs = hick_literate::equiv::compare_outputs(&first_files, &second_files);
    if diffs.is_empty() {
        let scope = match args.ignore_weave {
            true => ", ignoring each document's own weave",
            false => "",
        };
        eprintln!(
            "equivalent: {} and {} weave identical outputs ({} file(s){scope})",
            args.first.display(),
            args.second.display(),
            first_files.len(),
        );
        return Ok(ExitCode::SUCCESS);
    }
    for diff in &diffs {
        eprintln!("{}", hick_literate::equiv::format_diff(diff));
    }
    eprintln!(
        "NOT equivalent: {} output(s) differ between {} and {}",
        diffs.len(),
        args.first.display(),
        args.second.display(),
    );
    Ok(ExitCode::FAILURE)
}

/// Every output except the markdown file this document weaves for itself.
///
/// `bare-documents.md`: a document with no `weave=` weaves a `.md` of its own
/// name, which is right, and which makes two documents at different paths
/// inequivalent on that file alone. Dropping it compares what they GENERATE —
/// the question `hick equiv` is asked when the two are not the same file
/// before and after.
fn without_own_weave(
    files: &std::collections::HashMap<String, hick_exec::node::FileContent>,
    doc: &hick_lang::HickDocument,
) -> std::collections::HashMap<String, hick_exec::node::FileContent> {
    let Some(weave) = doc.weave_path.as_ref() else {
        return files.clone();
    };
    files
        .iter()
        .filter(|(path, _)| *path != weave)
        .map(|(path, content)| (path.clone(), content.clone()))
        .collect()
}
